@pytest.mark.parametrize('radius', [None, 0, 1, 3]) @pytest.mark.parametrize('mode,implementation', [('mixed', 'standard'), ('bf16', 'standard'), ('bf16', 'centered_fp32_scores')]) def test_shared_v_forward_backward_and_empty_rows(radius, mode, implementation): import jax import jax.numpy as jnp from flaxchat.encoder import bidirectional_attention, _rope assert jax.default_backend() == 'tpu' dtype = jnp.float32 if mode == 'mixed' else jnp.bfloat16 v = (jax.random.normal(jax.random.key(19), (1, 7, 2, 4)) * .2).astype(dtype) segments = jnp.array([[0, 0, 0, 0, 1, -1, -1]]) positions = jnp.arange(7)[None] def actual(v, alpha): z = _rope(v, positions, 160000.) return bidirectional_attention(z, z, v, segments, radius=radius, score='goat', alpha=alpha, yat_compute_mode=mode, yat_attention_block_size=3, yat_attention_implementation=implementation) def reference(v, alpha): z = _rope(v, positions, 160000.).astype(jnp.float32).transpose(0, 2, 1, 3) dot = jnp.einsum('bhid,bhjd->bhij', z, z) distance = ((z[:, :, :, None] - z[:, :, None, :]) ** 2).sum(-1) idx = jnp.arange(7) mask = (segments[:, :, None] == segments[:, None, :]) & (segments[:, :, None] >= 0) mask &= (idx[:, None] != idx[None, :])[None] if radius is not None: mask &= (abs(idx[:, None] - idx[None, :]) <= radius)[None] live = mask.any(-1) logits = alpha * (dot + 1)**2 / (distance + .01) logits = jnp.where(mask[:, None], logits, -jnp.inf) logits = jnp.where(live[:, None, :, None], logits, 0.) weights = jnp.where(live[:, None, :, None], jax.nn.softmax(logits, -1), 0.) return jnp.einsum('bhij,bjhd->bihd', weights, v.astype(jnp.float32)) alpha = jnp.float32(.1) output = jax.jit(actual)(v, alpha) assert np.isfinite(output.astype(jnp.float32)).all() np.testing.assert_array_equal(np.asarray(output[:, 4:], dtype=np.float32), 0) tolerance = .04 if mode == 'bf16' else 2e-5 > np.testing.assert_allclose(output.astype(jnp.float32), reference(v, alpha), atol=tolerance, rtol=tolerance) E AssertionError: E Not equal to tolerance rtol=2e-05, atol=2e-05 E E Mismatched elements: 12 / 56 (21.4%) E First 5 mismatches are at indices: E [0, 0, 1, 0]: -0.08592700958251953 (ACTUAL), -0.0857534408569336 (DESIRED) E [0, 0, 1, 1]: 0.22069168090820312 (ACTUAL), 0.22136688232421875 (DESIRED) E [0, 0, 1, 2]: 0.18952274322509766 (ACTUAL), 0.18966293334960938 (DESIRED) E [0, 0, 1, 3]: -0.0343017578125 (ACTUAL), -0.034626007080078125 (DESIRED) E [0, 1, 0, 0]: -0.1103672981262207 (ACTUAL), -0.11063814163208008 (DESIRED) E Max absolute difference among violations: 0.0006752 E Max relative difference among violations: 0.03756797 E ACTUAL: array([[[[ 0.055737, -0.075689, 0.099638, 0.383026], E [-0.085927, 0.220692, 0.189523, -0.034302]], E ... E DESIRED: array([[[[ 0.055737, -0.075689, 0.099638, 0.383026], E [-0.085753, 0.221367, 0.189663, -0.034626]], E ...
